[data-duim-1-9-0~="dui-m-spin"] { position: relative; width: 100%; height: 100%; }
[data-duim-1-9-0~="dui-m-spin-container"] { position: absolute; left: 50%; top: 50%; display: flex; -webkit-box-orient: horizontal; -webkit-box-direction: normal; flex-flow: row; -webkit-box-pack: center; justify-content: center; -webkit-box-align: center; align-items: center; width: 48px; height: 48px; }
[data-duim-1-9-0~="dui-m-spin-circle"] { border-radius: 50%; width: 100%; height: 100%; animation: 0.8s linear 0s infinite normal none running dui-m-spin-rotate; box-sizing: border-box; }
[data-duim-1-9-0~="dui-m-spin-circle-light"] { border-width: 4px; border-style: solid; border-color: rgb(255, 255, 255) rgba(255, 255, 255, 0.4) rgba(255, 255, 255, 0.4); border-image: initial; }
[data-duim-1-9-0~="dui-m-spin-circle-dark"] { border-width: 4px; border-style: solid; border-color: rgba(0, 0, 0, 0.32) rgba(0, 0, 0, 0.12) rgba(0, 0, 0, 0.12); border-image: initial; }
[data-duim-1-9-0~="dui-m-spin-circle-primary"] { border-right: 4px solid rgba(30, 111, 255, 0.24); border-bottom: 4px solid rgba(30, 111, 255, 0.24); border-left: 4px solid rgba(30, 111, 255, 0.24); border-image: initial; border-top: 4px solid var(--accent-default,#1e6fff); }
@-webkit-keyframes dui-m-spin-rotate { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(1turn); }
}
@keyframes dui-m-spin-rotate { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(1turn); }
}

[data-duim-1-9-0~="dui-m-button"] { outline: none; -webkit-tap-highlight-color: transparent; user-select: none; box-sizing: border-box; display: inline-block; white-space: nowrap; border-radius: 8px; font-size: 14px; font-weight: 500; border: 1px solid transparent; }
[data-duim-1-9-0~="dui-m-button"]:disabled { border-color: transparent; pointer-events: none; }
[data-duim-1-9-0~="dui-m-button-type-default"] { background: var(--bg-lv4-default,#fff); color: var(--text-link,#175ceb); }
[data-duim-1-9-0~="dui-m-button-type-default"]:active { background: var(--bg-lv4-medium,#f3f5f7); }
[data-duim-1-9-0~="dui-m-button-type-default"]:disabled { background: var(--bg-lv4-default,#fff); color: var(--accent-disabled,#c2d8ff); }
[data-duim-1-9-0~="dui-m-button-type-plain"] { background: var(--tsp-fill-medium,rgba(51,77,102,.08)); color: var(--text-ultrastrong,rgba(0,0,0,.9)); }
[data-duim-1-9-0~="dui-m-button-type-plain"]:active { background: var(--tsp-fill-strong,rgba(61,82,102,.12)); }
[data-duim-1-9-0~="dui-m-button-type-plain"]:disabled { color: var(--text-weak,rgba(0,0,0,.26)); background: var(--tsp-fill-weak,rgba(51,77,102,.06)); }
[data-duim-1-9-0~="dui-m-button-type-primary"] { background: var(--accent-default,#1e6fff); color: var(--text-white,#fff); }
[data-duim-1-9-0~="dui-m-button-type-primary"]:active { background: var(--accent-pressed,#134ae0); }
[data-duim-1-9-0~="dui-m-button-type-primary"]:disabled { color: rgba(255, 255, 255, 0.5); background: var(--accent-disabled,#c2d8ff); }
[data-duim-1-9-0~="dui-m-button-type-warning"] { background: var(--critical-default,#ff4747); color: var(--text-white,#fff); }
[data-duim-1-9-0~="dui-m-button-type-warning"]:active { background: var(--critical-pressed,#e02424); }
[data-duim-1-9-0~="dui-m-button-type-warning"]:disabled { color: var(--text-white,#fff); background: var(--critical-disabled,#fcc); }
[data-duim-1-9-0~="dui-m-button-type-hollow"] { background: rgb(255, 255, 255); color: var(--accent-default,#1e6fff); border-color: var(--accent-default,#1e6fff); }
[data-duim-1-9-0~="dui-m-button-type-hollow"]:active { opacity: 0.5; }
[data-duim-1-9-0~="dui-m-button-type-hollow"]:disabled { border-color: var(--accent-default,#1e6fff); opacity: 0.4; }
[data-duim-1-9-0~="dui-m-button-type-golden"] { background: linear-gradient(270deg, rgb(253, 198, 104), rgb(252, 219, 159)); border: none; color: rgba(0, 0, 0, 0.88); }
[data-duim-1-9-0~="dui-m-button-type-golden"]:active { background: linear-gradient(0deg, rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.08)), linear-gradient(270deg, rgb(253, 198, 104), rgb(252, 219, 159)); }
[data-duim-1-9-0~="dui-m-button-type-golden"]:disabled { opacity: 0.4; }
[data-duim-1-9-0~="dui-m-button-type-golden-dark"] { background: linear-gradient(113.69deg, rgb(69, 73, 82) 15.25%, rgb(39, 42, 51) 84.75%); border: none; color: rgb(250, 224, 165); }
[data-duim-1-9-0~="dui-m-button-type-golden-dark"]:active { background: linear-gradient(0deg, rgba(0, 0, 0, 0.32), rgba(0, 0, 0, 0.32)), linear-gradient(113.69deg, rgb(69, 73, 82) 15.25%, rgb(39, 42, 51) 84.75%); }
[data-duim-1-9-0~="dui-m-button-type-golden-dark"]:disabled { opacity: 0.4; }
[data-duim-1-9-0~="dui-m-button-type-golden-outline"] { border-color: rgb(219, 143, 28); color: rgb(219, 143, 28); background: var(--bg-lv4-default,#fff); }
[data-duim-1-9-0~="dui-m-button-type-golden-outline"]:active { opacity: 0.5; }
[data-duim-1-9-0~="dui-m-button-type-golden-outline"]:disabled { border-color: rgb(219, 143, 28); opacity: 0.4; }
[data-duim-1-9-0~="dui-m-button-size-large"] { min-width: 160px; height: 48px; padding: 0px 30px; font-size: 17px; border-radius: 12px; }
[data-duim-1-9-0~="dui-m-button-size-small"] { min-width: 52px; height: 28px; padding: 0px 8px; font-size: 12px; }
[data-duim-1-9-0~="dui-m-button-size-default"] { height: 32px; padding: 0px 7px; min-width: 56px; }

@-webkit-keyframes dui-m-snackbar-slide-in-top { 
  0% { opacity: 0; transform: scaleX(1) translateY(-100%); }
  100% { opacity: 1; transform: translateY(0px); }
}
@keyframes dui-m-snackbar-slide-in-top { 
  0% { opacity: 0; transform: scaleX(1) translateY(-100%); }
  100% { opacity: 1; transform: translateY(0px); }
}
@-webkit-keyframes dui-m-snackbar-slide-in-bottom { 
  0% { opacity: 0; transform: scaleX(1) translateY(100%); }
  100% { opacity: 1; transform: translateY(0px); }
}
@keyframes dui-m-snackbar-slide-in-bottom { 
  0% { opacity: 0; transform: scaleX(1) translateY(100%); }
  100% { opacity: 1; transform: translateY(0px); }
}
[data-duim-1-9-0~="dui-m-snackbar"] { box-sizing: border-box; position: fixed; z-index: 10000; display: flex; -webkit-box-orient: horizontal; -webkit-box-direction: normal; flex-flow: row; -webkit-box-pack: justify; justify-content: space-between; -webkit-box-align: center; align-items: center; left: 16px; right: 16px; height: 52px; padding: 0px 8px 0px 12px; font-size: 14px; color: var(--text-ultrastrong,rgba(0,0,0,.9)); border-radius: 8px; border: 1px solid var(--border-weak,rgba(0,0,0,.04)); animation-duration: 0.4s; animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1); transition-property: opacity, transform, -webkit-transform; transition-duration: 0.2s; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); background-color: var(--bg-lv3-default,#fff); box-shadow: rgba(0, 0, 0, 0.08) 0px 24px 48px 2px, rgba(0, 0, 0, 0.08) 0px 5px 12px 4px; }
[data-duim-1-9-0~="dui-m-snackbar"]::before { content: ""; display: inline-block; background-position: 50% center; background-repeat: no-repeat; background-size: contain; }
[data-duim-1-9-0~="dui-m-snackbar-icon-container"], [data-duim-1-9-0~="dui-m-snackbar"]::before { width: 24px; height: 24px; margin-right: 4px; }
[data-duim-1-9-0~="dui-m-snackbar-override-icon"]::before { display: none; }
[data-duim-1-9-0~="dui-m-snackbar-info"]::before { background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='48' height='48' fill-rule='evenodd'%3E%3Ccircle cx='24' cy='24' r='18' fill='%231e6fff'/%3E%3Cpath fill='%23fff' d='M26 21v12h2v2h-8v-2h2V23h-2v-2h6zm-2-8a3 3 0 1 1 0 6 3 3 0 1 1 0-6z'/%3E%3C/svg%3E"); }
[data-duim-1-9-0~="dui-m-snackbar-success"]::before { background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='48' height='48' fill-rule='evenodd'%3E%3Ccircle cx='24' cy='24' r='18' fill='%2304dd7d'/%3E%3Cpath fill='%23fff' d='M17.93 22l3.95 3.95 9.9-9.9 2.828 2.83L21.88 31.607l-6.778-6.78L17.93 22z'/%3E%3C/svg%3E"); }
[data-duim-1-9-0~="dui-m-snackbar-error"]::before, [data-duim-1-9-0~="dui-m-snackbar-warning"]::before { background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='48' height='48' fill-rule='evenodd'%3E%3Ccircle cx='24' cy='24' r='18' fill='%23fb4d3f'/%3E%3Cpath fill='%23fff' d='M24 29a3 3 0 1 1 0 6 3 3 0 1 1 0-6zm3-16l-1 14h-4l-1-14h6z'/%3E%3C/svg%3E"); }
[data-duim-1-9-0~="dui-m-snackbar-loading"]::before { content: none; }
[data-duim-1-9-0~="dui-m-snackbar-loading-indicator"] { width: 18px; height: 18px; margin: 0px 7px 0px 3px; }
[data-duim-1-9-0~="dui-m-snackbar-loading-indicator-circle"] { border-width: 8px; }
[data-duim-1-9-0~="dui-m-snackbar-top"] { animation-name: dui-m-snackbar-slide-in-top; top: 16px; margin-top: env(safe-area-inset-top); }
[data-duim-1-9-0~="dui-m-snackbar-top"][data-duim-1-9-0~="dui-m-snackbar-hidden"] { opacity: 0; transform: scaleX(1) translateY(-100%); }
[data-duim-1-9-0~="dui-m-snackbar-bottom"] { animation-name: dui-m-snackbar-slide-in-bottom; bottom: 16px; margin-bottom: env(safe-area-inset-bottom); }
[data-duim-1-9-0~="dui-m-snackbar-bottom"][data-duim-1-9-0~="dui-m-snackbar-hidden"] { opacity: 0; transform: scaleX(1) translateY(100%); }
[data-duim-1-9-0~="dui-m-snackbar-message"] { -webkit-box-flex: 1; flex: 1 1 0%; overflow: hidden; text-overflow: ellipsis; }
[data-duim-1-9-0~="dui-m-snackbar-action"] { min-width: 0px; font-weight: 600; }
[data-duim-1-9-0~="dui-m-snackbar-actions"] > [data-duim-1-9-0~="dui-m-snackbar-action"]:not(:first-child) { margin-left: 6px; }
[data-duim-1-9-0~="dui-m-snackbar-close"] { width: 24px; height: 24px; margin-left: 4px; background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='16' height='16' fill='none'%3E%3Ccircle cx='8' cy='8' r='8' fill='%23000' fill-opacity='.16'/%3E%3Cpath fill-rule='evenodd' d='M10.833 10.832a.584.584 0 0 0 .004-.814L8.822 8.002l2.015-2.02a.584.584 0 0 0-.004-.814.58.58 0 0 0-.814-.004L7.999 7.18l-2.02-2.02c-.209-.209-.592-.218-.814.004s-.218.605-.004.818l2.02 2.02-2.02 2.02a.59.59 0 0 0 .004.814.593.593 0 0 0 .814.004l2.02-2.02 2.02 2.015a.58.58 0 0 0 .814-.004z' fill='%23fff'/%3E%3C/svg%3E"); background-size: 16px; background-position: 50% center; background-repeat: no-repeat; }
[data-duim-1-9-0~="dui-m-snackbar-close"]:active { opacity: 0.5; }

*, ::before, ::after { box-sizing: border-box; }
html, body, #root { margin: 0px; padding: 0px; width: 100%; height: 100%; overflow: hidden; }
body { background-color: var(--vscode-editor-background, #ffffff); color: var(--vscode-editor-foreground, #3b3b3b); font-family: var(--vscode-font-family, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif); font-size: var(--vscode-font-size, 13px); -webkit-font-smoothing: antialiased; }
body[data-vscode-theme-name="IDE Light"] { --vscode-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif; --vscode-font-size: 13px; --vscode-editor-font-family: Menlo, Monaco, "Courier New", monospace; --vscode-editor-font-size: 14px; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background-color: var(--vscode-scrollbarSlider-background, rgba(100, 100, 100, 0.4)); }
::-webkit-scrollbar-thumb:hover { background-color: var(--vscode-scrollbarSlider-hoverBackground, rgba(100, 100, 100, 0.7)); }
::-webkit-scrollbar-thumb:active { background-color: var(--vscode-scrollbarSlider-activeBackground, rgba(0, 0, 0, 0.6)); }

